Use @ResponseStatus when the code never changes; ResponseEntity when status, headers, or body vary per request.

@RestController
@RequestMapping("/api/users")
public class UserController {
    private final UserRepository userRepository;

    // Single object - return Optional, handle 404
    @GetMapping("/{id}")
    public ResponseEntity<User> getUserById(@PathVariable Long id) {
        return userRepository.findById(id)
            .map(ResponseEntity::ok)  // 200 with user if found
            .orElse(ResponseEntity.notFound().build());  // 404 if missing
    }

    // Collection - paginated by default
    @GetMapping
    public Page<User> getAllUsers(Pageable pageable) {
        return userRepository.findAll(pageable);  // Spring handles serialization
    }

    // Search - also paginated
    @GetMapping("/search")
    public Page<User> searchUsers(@RequestParam String name, Pageable pageable) {
        return userRepository.findByNameContaining(name, pageable);
    }
}

@RestController
@RequestMapping("/api/products")
public class ProductController {
    @Autowired
    private ProductService productService;

    @PostMapping
    public ResponseEntity<Product> createProduct(@RequestBody ProductRequest request) {
        var product = productService.create(request);
        var headers = new HttpHeaders();
        headers.setLocation(URI.create("/api/products/" + product.id())); // Location header
        headers.setCacheControl(CacheControl.noCache());  // No caching for mutations
        return ResponseEntity.status(HttpStatus.CREATED).headers(headers).body(product);
    }

    @GetMapping("/{id}")
    public ResponseEntity<Product> getProduct(@PathVariable Long id) {
        var product = productService.findById(id).orElseThrow();
        var headers = new HttpHeaders();
        headers.setCacheControl(CacheControl.maxAge(300, TimeUnit.SECONDS)); // Cache for 5 min
        headers.add("X-Request-ID", UUID.randomUUID().toString()); // Custom trace header
        return ResponseEntity.ok().headers(headers).body(product);
    }
}

@RestController
@RequestMapping("/api/customers")
public class CustomerController {
    @Autowired
    private CustomerService customerService;

    @GetMapping("/{id}")
    public ResponseEntity<Customer> getCustomer(@PathVariable Long id) {
        return customerService.findById(id)
            .map(ResponseEntity::ok)                    // 200 if found
            .orElse(ResponseEntity.notFound().build()); // 404 if missing
    }

    @GetMapping("/{id}/status")
    public ResponseEntity<?> getCustomerStatus(@PathVariable Long id) {
        var customer = customerService.findById(id);
        if (customer.isEmpty()) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                .body(new ErrorResponse("Customer not found")); // Different body type
        }
        return ResponseEntity.ok(new StatusResponse(customer.get().status()));
    }

    @PostMapping("/{id}/activate")
    public ResponseEntity<Customer> activateCustomer(@PathVariable Long id) {
        return customerService.activate(id)
            .map(ResponseEntity::ok)
            .orElseGet(() -> ResponseEntity.status(HttpStatus.CONFLICT)
                .body(null)); // 409 if already active
    }
}
